mapper.select:
select mn.*,pro.P_Name as projectName,reg.audit_status as auditStatus,reg.audit_comment as auditComment
from Pre_Project_Solution mn
left join Pre_Project pro on mn.project_id = pro.P_ID
left join Project_Register_Info reg on mn.project_register_info_id = reg.id

    mn.lastest = 1
    
        and pro.P_Name like concat('%',#{params.projectName},'%')
    
    
        and mn.project_id = #{params.projectId}
    
    
        and pro.P_Code like concat('%',#{params.projectCode},'%')
    
    
        and mn.audit_status = #{params.auditStatus}
    
    
        and mn.create_uid = #{params.createUid}

select mn.*
from Project_Register_Info mn
where mn.solution_id= #{id}

select mn.*,pro.P_Name as projectName,reg.audit_status as
    auditStatus,reg.audit_comment as auditComment,reg.solution_id as solutionId
from Pre_Project_Solution mn
left join Pre_Project pro on mn.project_id = pro.P_ID
left join Project_Register_Info reg on mn.project_register_info_id = reg.id

    mn.version_id = #{params.versionId}
    
        and pro.P_Name like concat('%',#{params.projectName},'%')
    
    
        and mn.project_id = #{params.projectId}
    
    
        and pro.P_Code like concat('%',#{params.projectCode},'%')
    
    
        and mn.audit_status = #{params.auditStatus}
    
    
        and mn.create_uid = #{params.createUid}
